WITH unpacked AS (SELECT id, customer_id, attributes, attributes['utm_source'] AS utm_source, COALESCE(ship_to.city, 'UNKNOWN') AS city_or_unknown FROM carts) SELECT customer_id, COUNT(*) AS event_count, COUNT(*) AS event_count_2, COUNT(DISTINCT city_or_unknown) AS distinct_city_or_unknowns, COUNT(DISTINCT utm_source) AS distinct_utm_sources, COUNT(DISTINCT id) AS distinct_ids, COUNT(*) AS cnt FROM unpacked GROUP BY customer_id HAVING COUNT(*) < 1000 ORDER BY event_count DESC;
